//! Compatibility tests against outputs recorded from the reference fastText
//! library. Fixtures live in `tests/data/` and are generated by
//! `scripts/make_fixtures.py`.

use std::fs;
use std::path::{Path, PathBuf};

use fasttext_turbo::{Model, PredictOptions};

const MAGIC: u32 = 0x4654_4631;
const TOL: f32 = 2e-5;

struct Cursor<'a> {
    b: &'a [u8],
    p: usize,
}

impl<'a> Cursor<'a> {
    fn u32(&mut self) -> u32 {
        let v = u32::from_le_bytes(self.b[self.p..self.p + 4].try_into().unwrap());
        self.p += 4;
        v
    }
    fn f32(&mut self) -> f32 {
        let v = f32::from_le_bytes(self.b[self.p..self.p + 4].try_into().unwrap());
        self.p += 4;
        v
    }
    fn bytes(&mut self, n: usize) -> &'a [u8] {
        let s = &self.b[self.p..self.p + n];
        self.p += n;
        s
    }
    fn string(&mut self) -> String {
        let n = self.u32() as usize;
        String::from_utf8(self.bytes(n).to_vec()).unwrap()
    }
}

struct Case {
    k: usize,
    threshold: f32,
    expected: Vec<Vec<(String, f32)>>,
}

struct Fixture {
    lines: Vec<String>,
    cases: Vec<Case>,
}

fn read_fixture(path: &Path) -> Fixture {
    let data = fs::read(path).unwrap();
    let mut c = Cursor { b: &data, p: 0 };
    assert_eq!(c.u32(), MAGIC, "bad fixture magic in {}", path.display());
    let nlines = c.u32() as usize;
    let mut lines = Vec::with_capacity(nlines);
    for _ in 0..nlines {
        lines.push(c.string());
    }
    let ncases = c.u32() as usize;
    let mut cases = Vec::with_capacity(ncases);
    for _ in 0..ncases {
        let k = c.u32() as usize;
        let threshold = c.f32();
        let count = c.u32() as usize;
        assert_eq!(count, nlines);
        let mut expected = Vec::with_capacity(count);
        for _ in 0..count {
            let npred = c.u32() as usize;
            let mut row = Vec::with_capacity(npred);
            for _ in 0..npred {
                let p = c.f32();
                let label = c.string();
                row.push((label, p));
            }
            expected.push(row);
        }
        cases.push(Case {
            k,
            threshold,
            expected,
        });
    }
    assert_eq!(c.p, data.len(), "trailing bytes in {}", path.display());
    Fixture { lines, cases }
}

fn opts(k: usize, threshold: f32, threads: usize) -> PredictOptions {
    PredictOptions {
        k,
        threshold,
        threads,
        batch_size: 0,
        append_eos: true,
        norm_skip: true,
    }
}

fn model_files() -> Vec<PathBuf> {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/models");
    let mut out: Vec<_> = fs::read_dir(dir)
        .unwrap()
        .filter_map(|e| {
            let p = e.unwrap().path();
            match p.extension().and_then(|s| s.to_str()) {
                Some("bin") | Some("ftz") => Some(p),
                _ => None,
            }
        })
        .collect();
    out.sort();
    out
}

fn check_rows(
    model_name: &str,
    case: &str,
    line: &str,
    got: &[fasttext_turbo::Prediction<'_>],
    expected: &[(String, f32)],
) {
    assert_eq!(
        got.len(),
        expected.len(),
        "{model_name}/{case}: wrong number of predictions for {line:?}: got {got:?}, expected {expected:?}"
    );
    for (i, (g, (want_label, want_p))) in got.iter().zip(expected).enumerate() {
        assert_eq!(
            g.label, want_label,
            "{model_name}/{case}: label {i} differs for {line:?}"
        );
        let diff = (g.probability - want_p).abs();
        // Batch kernels sum in a different order, and fastText's own
        // probabilities carry a 1e-5 bias; both are far below this tolerance.
        assert!(
            diff <= TOL + TOL * want_p.abs(),
            "{model_name}/{case}: probability {i} for {line:?} differs by {diff} \
             (got {}, want {want_p})",
            g.probability
        );
    }
}

#[test]
fn matches_reference_fasttext() {
    let models = model_files();
    assert!(!models.is_empty(), "no fixture models found");
    let mut checked_models = 0;
    let mut checked_cases = 0;

    for path in models {
        let stem = path.file_stem().unwrap().to_str().unwrap();
        let fixture_path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/data")
            .join(format!("fixtures_{stem}.ftf"));
        if !fixture_path.exists() {
            continue;
        }
        let fixture = read_fixture(&fixture_path);
        let model = Model::load(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        let refs: Vec<&str> = fixture.lines.iter().map(String::as_str).collect();

        for (ci, case) in fixture.cases.iter().enumerate() {
            let name = format!("case{ci}");

            // Serial, batched.
            let got = model
                .predict_batch(&refs, &opts(case.k, case.threshold, 1))
                .unwrap();
            assert_eq!(got.len(), refs.len());
            for (i, (g, e)) in got.iter().zip(&case.expected).enumerate() {
                check_rows(stem, &name, &fixture.lines[i], g, e);
            }

            // Several threads, in input order.
            let parallel = model
                .predict_batch(&refs, &opts(case.k, case.threshold, 4))
                .unwrap();
            for (i, (g, e)) in parallel.iter().zip(&case.expected).enumerate() {
                check_rows(stem, &format!("{name}/parallel"), &fixture.lines[i], g, e);
            }

            // The single-line path uses a different scoring kernel.
            for (i, line) in fixture.lines.iter().enumerate() {
                let got = model
                    .predict(line, &opts(case.k, case.threshold, 1))
                    .unwrap();
                check_rows(
                    stem,
                    &format!("{name}/single"),
                    line,
                    &got,
                    &case.expected[i],
                );
            }
            checked_cases += 1;
        }
        checked_models += 1;
    }

    assert!(
        checked_models >= 12,
        "expected at least 12 model fixtures, got {checked_models}"
    );
    assert!(checked_cases >= 34, "expected at least 34 cases");
}

#[test]
fn api_edge_cases() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/models/dense_softmax.bin");
    let model = Model::load(&path).unwrap();

    // k = 0 returns nothing; k larger than the label set returns every label.
    let none = model
        .predict(
            "good great",
            &PredictOptions {
                k: 0,
                ..PredictOptions::default()
            },
        )
        .unwrap();
    assert!(none.is_empty());
    let all = model
        .predict(
            "good great",
            &PredictOptions {
                k: 100,
                ..PredictOptions::default()
            },
        )
        .unwrap();
    assert_eq!(all.len(), model.nlabels());

    // An impossible threshold filters everything.
    let filtered = model
        .predict(
            "good great",
            &PredictOptions {
                k: 3,
                threshold: 1.0,
                ..PredictOptions::default()
            },
        )
        .unwrap();
    assert!(filtered.is_empty());

    // append_eos=false on an empty line has no features and no predictions.
    let opts_no_eos = PredictOptions {
        append_eos: false,
        ..PredictOptions::default()
    };
    assert!(model.predict("", &opts_no_eos).unwrap().is_empty());
    assert!(!model
        .predict("", &PredictOptions::default())
        .unwrap()
        .is_empty());

    // Word n-grams sign-extend 32-bit token hashes; these four bigram ids are
    // what fastText itself produces for this model (bucket 500).
    let ns =
        Model::load(Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/models/dense_ns.bin"))
            .unwrap();
    let ids = ns.feature_ids("good great excellent movie", true);
    assert_eq!(ids.len(), 78);
    assert_eq!(&ids[ids.len() - 4..], &[234, 635, 326, 202]);

    // A newline terminates processing, as in fastText's readWord/getLine.
    assert_eq!(
        model.feature_ids("good\nthis must be ignored", true),
        model.feature_ids("good", true)
    );
    // A newline produces EOS even when append_eos is false: the newline is
    // part of the text, not an API convenience.
    assert_eq!(
        model.feature_ids("good\nignored", false),
        model.feature_ids("good", true)
    );
    assert_ne!(
        model.feature_ids("good\nignored", false),
        model.feature_ids("good", false)
    );

    // A literal </s> token ends the line, and an unknown label-prefixed token
    // is not a feature.
    assert_eq!(
        model.feature_ids("good </s> ignored", true),
        model.feature_ids("good", true)
    );
    assert_eq!(
        model.feature_ids("__label__unknown good", true),
        model.feature_ids("good", true)
    );

    // Batch sizes 1 and 8 exercise the line kernel and the blocked kernel.
    let lines = [
        "good great",
        "terrible awful",
        "",
        "\u{043e}\u{0442}\u{043b}\u{0438}\u{0447}\u{043d}\u{043e}",
        "\u{597d}",
    ];
    let a = model
        .predict_batch(
            &lines,
            &PredictOptions {
                k: 2,
                threads: 1,
                batch_size: 1,
                ..PredictOptions::default()
            },
        )
        .unwrap();
    let b = model
        .predict_batch(
            &lines,
            &PredictOptions {
                k: 2,
                threads: 4,
                batch_size: 8,
                ..PredictOptions::default()
            },
        )
        .unwrap();
    assert_eq!(a.len(), lines.len());
    for (x, y) in a.iter().zip(&b) {
        assert_eq!(x.len(), y.len());
        for (p, q) in x.iter().zip(y) {
            assert_eq!(p.label, q.label);
            assert!((p.probability - q.probability).abs() < 1e-5);
        }
    }

    // Byte API accepts the same text and arbitrary non-UTF-8 bytes.
    assert_eq!(
        model.feature_ids_bytes(b"good great", true),
        model.feature_ids("good great", true)
    );
    let raw = model
        .predict_bytes(b"bad \xff\xfe text", &PredictOptions::k(2))
        .unwrap();
    assert_eq!(raw.len(), 2);
    let raw_rows = model
        .predict_batch_bytes(
            &[b"good".as_slice(), b"bad \xff".as_slice()],
            &PredictOptions::k(2),
        )
        .unwrap();
    assert_eq!(raw_rows.len(), 2);

    // Owned-string convenience wrapper.
    let owned: Vec<String> = lines.iter().map(|s| s.to_string()).collect();
    let c = model
        .predict_batch_owned(&owned, &PredictOptions::k(2))
        .unwrap();
    assert_eq!(c.len(), lines.len());

    // An absurd batch size must not overflow the chunk arithmetic.
    let huge = model
        .predict_batch(
            &lines,
            &PredictOptions {
                k: 2,
                batch_size: usize::MAX,
                ..PredictOptions::default()
            },
        )
        .unwrap();
    assert_eq!(huge.len(), lines.len());
}

#[test]
fn word_cache_is_used_only_when_it_can_help() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/models");
    let with_ngrams = Model::load(dir.join("dense_softmax.bin")).unwrap();
    let (words, bytes) = with_ngrams.word_cache_stats().expect("cache expected");
    assert_eq!(words, with_ngrams.dictionary().nwords());
    assert!(bytes > 0);
    // Character n-grams are what make the cache worthwhile; a model with
    // maxn=0 gets no cache.
    let without = Model::load(dir.join("dense_nonchar.bin")).unwrap();
    assert!(without.word_cache_stats().is_none());
}

#[test]
fn model_is_send_and_sync() {
    fn check<T: Send + Sync>() {}
    check::<Model>();
    check::<fasttext_turbo::Prediction<'static>>();
}

#[test]
fn unsupervised_models_load_but_cannot_predict() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/models/unsup.bin");
    let model = Model::load(&path).unwrap();
    assert!(!model.is_supervised());
    assert!(model.predict("hello world", &PredictOptions::k(1)).is_err());
    assert!(model
        .predict_batch(&["hello"], &PredictOptions::k(1))
        .is_err());
    assert!(model.predictor().is_err());
}

#[test]
fn bad_files_are_rejected_without_panicking() {
    let good =
        fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/models/dense_softmax.bin"))
            .unwrap();

    let dir = std::env::temp_dir();
    let pid = std::process::id();

    let truncated = dir.join(format!("ftt-truncated-{pid}.bin"));
    fs::write(&truncated, &good[..good.len() / 2]).unwrap();
    assert!(Model::load(&truncated).is_err());

    let mut bad_magic = good.clone();
    bad_magic[0] ^= 0xff;
    let bad = dir.join(format!("ftt-badmagic-{pid}.bin"));
    fs::write(&bad, &bad_magic).unwrap();
    assert!(Model::load(&bad).is_err());

    let missing = dir.join("ftt-does-not-exist-12345.bin");
    assert!(Model::load(&missing).is_err());

    let _ = fs::remove_file(&truncated);
    let _ = fs::remove_file(&bad);

    // Header fields must not be able to request huge allocations. The
    // dictionary header starts after magic + args: 8 + 56 = 64.
    let huge = dir.join(format!("ftt-huge-{pid}.bin"));
    let mut bytes = good.clone();
    bytes[64..68].copy_from_slice(&1_000_000_000i32.to_le_bytes());
    bytes[68..72].copy_from_slice(&1_000_000_000i32.to_le_bytes());
    bytes[72..76].copy_from_slice(&0i32.to_le_bytes());
    fs::write(&huge, &bytes).unwrap();
    assert!(Model::load(&huge).is_err());

    // Extreme signed 32-bit counts must not overflow the size check.
    bytes[64..68].copy_from_slice(&i32::MAX.to_le_bytes());
    bytes[68..72].copy_from_slice(&i32::MAX.to_le_bytes());
    bytes[72..76].copy_from_slice(&i32::MAX.to_le_bytes());
    fs::write(&huge, &bytes).unwrap();
    assert!(Model::load(&huge).is_err());

    let mut bytes = good.clone();
    bytes[84..92].copy_from_slice(&1_000_000_000i64.to_le_bytes());
    fs::write(&huge, &bytes).unwrap();
    assert!(Model::load(&huge).is_err());
    let _ = fs::remove_file(huge);

    // Every truncation of a valid model must produce an error, never a panic
    // or an out-of-bounds read.
    for cut in (0..good.len()).step_by(4096) {
        fs::write(&truncated, &good[..cut]).unwrap();
        assert!(
            Model::load(&truncated).is_err(),
            "truncated model at {cut} bytes was accepted"
        );
    }
    let _ = fs::remove_file(truncated);
}

/// Runs against a real, larger model when one is provided. This is not part of
/// the checked-in fixture set because model files are large.
#[test]
fn optional_external_model() {
    let Some(path) = std::env::var_os("FASTTEXT_TURBO_MODEL") else {
        return;
    };
    let model = Model::load(&path).expect("load FASTTEXT_TURBO_MODEL");
    assert!(model.is_supervised());
    let lines = [
        "Hello, how are you today?",
        "Bonjour tout le monde",
        "\u{041f}\u{0440}\u{0438}\u{0432}\u{0435}\u{0442}, \u{043a}\u{0430}\u{043a} \u{0434}\u{0435}\u{043b}\u{0430}?",
        "\u{4f60}\u{597d}\u{ff0c}\u{4eca}\u{5929}\u{8fc7}\u{5f97}\u{600e}\u{4e48}\u{6837}\u{ff1f}",
        "",
    ];
    let preds = model
        .predict_batch(&lines, &PredictOptions::k(5))
        .expect("predict");
    assert_eq!(preds.len(), lines.len());
    for row in &preds {
        assert_eq!(row.len(), 5);
        for p in row {
            assert!(p.probability.is_finite());
            assert!(p.label.starts_with("__label__"));
        }
    }
}

#[test]
fn flat_batch_output_matches_nested_output() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/models/dense_softmax.bin");
    let model = Model::load(&path).unwrap();
    let lines: Vec<&[u8]> = vec![b"good great", b"bad \xff", b"", b"unseen qwerty", b"good"];
    let opts = PredictOptions::k(3);
    let mut flat = Vec::new();
    let mut lengths = Vec::new();
    model
        .predict_batch_bytes_into(&lines, &opts, &mut flat, &mut lengths)
        .unwrap();
    assert_eq!(lengths.len(), lines.len());
    assert_eq!(flat.len(), lengths.iter().sum::<usize>());

    let nested = model.predict_batch_bytes(&lines, &opts).unwrap();
    let mut pos = 0;
    for (row, &len) in nested.iter().zip(&lengths) {
        assert_eq!(row.len(), len);
        for (a, b) in row.iter().zip(&flat[pos..pos + len]) {
            assert_eq!(a.label, b.label);
            assert_eq!(a.probability, b.probability);
        }
        pos += len;
    }

    // Reusing the buffers must clear and refill them.
    model
        .predict_batch_bytes_into(&lines, &opts, &mut flat, &mut lengths)
        .unwrap();
    assert_eq!(lengths.len(), lines.len());
    assert_eq!(flat.len(), lengths.iter().sum::<usize>());
}

#[test]
fn norm_skip_path_matches_exhaustive_scoring() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/models/quant_qout.ftz");
    let model = Model::load(&path).unwrap();
    assert!(model.norm_skip_status().is_some(), "expected norm blocks");
    let lines = [
        "shared alpha beta group3 w17_4 w17_5",
        "shared alpha beta group5 w299_1 w299_2",
        "w0_0 w1_1 w2_2",
        "",
    ];
    let fast = model
        .predict_batch(
            &lines,
            &PredictOptions {
                k: 5,
                norm_skip: true,
                threads: 1,
                ..PredictOptions::default()
            },
        )
        .unwrap();
    let exhaustive = model
        .predict_batch(
            &lines,
            &PredictOptions {
                k: 5,
                norm_skip: false,
                threads: 1,
                ..PredictOptions::default()
            },
        )
        .unwrap();
    for (a, b) in fast.iter().zip(&exhaustive) {
        assert_eq!(a.len(), b.len());
        for (x, y) in a.iter().zip(b) {
            assert_eq!(x.label, y.label);
            assert!(
                (x.probability - y.probability).abs() <= 2e-5,
                "norm skip changed {}: {} vs {}",
                x.label,
                x.probability,
                y.probability
            );
        }
    }
}
